  "ネオンリンク？……喂勇樹，是你們公司嗎？（勇樹的臉一下子白了）": `ネオンリンク？……ねえ君、君の会社？（勇樹の顔が真っ青になる）`,
  "ヒロコウ是上野廣小路，「歌之城」是那棟卡拉OK大樓。電梯到 7，再走樓梯——ハチ，八樓。": `ヒロコウは上野広小路、“歌の城”はあのカラオケビル。エレベーターで7階、そこから階段——ハチ、8階。`,
