  "上野公園口旁的長椅上有個被遺忘的錢包。在日本，撿到東西就送去交番。": `上野・公園口そばのベンチに財布の忘れ物。日本では、拾ったものは交番へ。`,
  "上野公園，公園口旁邊步道的長椅上。": `上野公園の、公園口そばの遊歩道のベンチです。`,
