  "下禮拜天中午，步行者天國。那個人一定會出現。我開直播幫你盯——我的觀眾眼睛可多了。": `来週の日曜、歩行者天国。そいつは絶対来る。私が配信して一緒に見張るよ——うちの視聴者、目がいっぱいあるから。`,
