  "不好意思，我在公園撿到這個錢包。": `すみません、公園でこの財布を拾いました。`,
  "不好意思，我是警察。可以跟你聊一下嗎？": `すみません、警察です。ちょっとお話いいですか。`,
  "不好意思，有沒有看到穿紅色開襟衫、拿熊貓氣球的女生？": `すみません、赤いカーディガンでパンダの風船を持った女の人、見ませんでしたか？`,
  "不好意思，現在要回家了嗎？": `すみません、今お帰りですか？`,
  "不好意思，請問一下——": `すみません、ちょっと——`,
  "不好意思，請問乾貨店是在這條巷子裡面嗎？我眼睛不太好……": `ちょっとすみません、乾物屋さんはこの路地の中だったかしら？目が悪くてねえ……`,
  "不好意思，這塊布……有人嗎？我們公司想用這裡。": `すみません、このシート……どなたか使ってます？うちの会社、ここを使いたいんですが。`,
  "不好意思，這孩子跟媽媽走散了。": `すみません、この子、お母さんとはぐれちゃって。`,
  "不好意思～這裡是街頭訪問！今天下班後要去哪裡呢？": `すみませ～ん、街頭インタビューです！今日はお仕事の後、どちらへ？`,
