  人群: `客`,
  "什麼啊，這人。走吧走吧。": `なにこの人。行こ行こ。`,
  "什麼活動？在哪裡？": `どんなイベントですか？どこで？`,
  "什麼都1,000日圓！": `なんでも1,000円！`,
  "什麼！？": `なにっ！？`,
  "今天……剛剛吧？": `今日……さっき、だと思います。`,
  "今天不賺錢啦！": `今日はもう儲けなし！`,
  "今天也辛苦了！": `今日も一日お疲れさま！`,
  "今天先回去吧……下次加油。": `今日はもう上がっていいよ……次は頑張って。`,
  "今天店裡進不去……改天再來吧。": `今日は店に入れない……また今度。`,
  "今天是我店裡的卡丁車遊行：從這裡到東京車站，整條路為我們封十分鐘。": `今日はうちの店のカートパレードだ。ここから東京駅まで、十分間だけ道を貸し切りにしてある。`,
  "今天最後一批囉！": `今日はこれで最後だよ！`,
  今天的步行者天國人好多: `今日のホコ天人多すぎ`,
  "今天真熱鬧呢。是有什麼活動嗎？": `今日は人が多いですねえ。何かあるのかな。`,
