  "今日金價 每克{price}": `本日の金 1g {price}`,
  今日限定特價: `本日限りの特価`,
  "今晚也為您送上演歌。": `今夜も、あなたの心に演歌をお届けします。`,
  "今晚店裡的夜跑剛好封了路——油門踩到底，甩掉他們！": `今夜はうちの店の夜走りで道を押さえてある——踏み込め、振り切るぞ！`,
  "他一直在看手機！": `ずっとスマホ見てる！`,
  "他們不用傳什麼！他們知道她七點會在哪裡啊！": `送る必要なんてない！七時にどこにいるか知ってるんだから！`,
  "他們傳了我妹的照片給我。在錦糸町的補習班門口……她七點下課。": `妹の写真が送られてきたんです。錦糸町の塾の前で……七時に終わるんです。`,
  "他們叫我帶著這支手機在秋葉原晃，讓它的位置看起來像主人還在這裡逛街……一天一萬。": `この携帯持って秋葉原ブラブラしろって。持ち主がまだ買い物してるみたいに見せるために……日給一万。`,
  "他們拍了你證件的照片，對吧？跟勇樹一樣。": `身分証の写真、撮られたんだろ？勇樹と同じだ。`,
  "他們拿你媽媽來讓你害怕。錯的是他們，不是你。": `母さんを使って怖がらせてるんだ。悪いのはあいつらで、君じゃない。`,
  "他們逼我們打電話給老人家，說是孫子出了車禍……我偷拍了名單。這些人都是被騙的對象。": `（中国語で）お年寄りに電話させられたの。孫が事故に遭ったって……リストをこっそり撮った。ここに載ってる人、みんな騙される側なの。`,
  "他先到了——你沒看到他上了幾樓": `先を越された——何階に行ったか見られなかった`,
  "他剛從我旁邊經過，咖啡色頭髮，染的": `今横通った。茶髪だった`,
  "他嚇壞了……": `怯えてる……`,
  他嚇得什麼都不肯說了: `怯えて、何も話してくれなかった`,
  "他在買花……一大束玫瑰，要送誰？拍下來！": `花屋でバラを買っている……誰に？撮れ！`,
  他抵達: `彼が着く`,
  "他有槍，小心！": `拳銃を持ってるぞ、気をつけろ！`,
  他消失在人群裡了: `男は人混みに消えた`,
  他的車: `彼の車`,
  "他走出了步行者天國，訊號消失在人群裡": `ホコ天を出て、電波は人混みに消えた`,
  "他走進有樂町高架橋下的烤串店……拍下來！": `有楽町ガード下の焼き鳥屋に入った……撮れ！`,
  "他跑了！！": `逃げた！！`,
  "他還說，萬一出事，公司會請律師。「一個都不會丟下」。": `それに、何かあったら会社が弁護士をつけるって。「誰も見捨てない」って。`,
  "他鑽進人群裡，不見了": `人混みにまぎれて、見失った`,
  他離開步行者天國: `ホコ天を出る`,
