  佐伯先生: `佐伯さん`,
  "佐伯先生，恭候多時。……是的，照您吩咐，緞帶用銀色的。": `佐伯様、お待ちしておりました。……はい、ご指定どおり、リボンは銀色で。`,
  "佐藤 鈴木 高橋 田中 渡邊 伊藤 山本 中村 小林 加藤": `佐藤 鈴木 高橋 田中 渡辺 伊藤 山本 中村 小林 加藤`,
  佔位子: `場所取り`,
  你: `あなた`,
  "你不用為組裡做任何事。組裡也絕對不碰那些孩子。這是仁義。": `あんたは組のために何もしなくていい。組も、あのガキどもには指一本触れねえ。それが仁義だ。`,
  你丟下了源さん的計程車: `源さんのタクシーを放り出した`,
  "你以為你是誰？": `何様のつもりですか。`,
  "你在御徒町的喫茶店和鬼頭老大打了花札。他給了你客服中心的平面圖，條件是你不為組裡做任何事。": `御徒町の喫茶店で鬼頭の親分と花札を打った。コールセンターの見取り図をくれたが、条件は組のために何もしないことだった。`,
  "你在攤位打烊前湊齊了零件，ミコ做出了追蹤器。": `閉店前にパーツをそろえ、ミコが追跡機を組み上げた。`,
  "你在隔壁包廂唱歌掩護，竊聽到神城的「大案子」：銀座，星期六。被發現後，你跳上轟的卡丁車隊逃走。": `隣の部屋で歌ってごまかしながら、神城の「大仕事」を盗聴した。銀座、土曜日。見つかって、轟のカートツアーにまぎれて逃げた。`,
  "你在高速公路下贏了辰，他的手機透露了被關的打工者在哪裡。": `首都高の下で辰に勝ち、奴の携帯から闇バイトの子たちの居場所がわかった。`,
  "你媽媽那邊沒事了，桐島的人守在你家門口。你可以放心。": `お母さんは大丈夫。桐島の部下が家の前にいる。もう心配いらない。`,
  "你就坐在交番旁邊。走進去只要三步。": `交番のすぐ横じゃないか。三歩で入れる。`,
  "你就是來應徵的人吧？外國人也沒關係，只要肯做。": `バイトの応募の子だね？外国の人でも大丈夫、やる気があれば。`,
  "你就是小晴的……！她每個禮拜都來店裡，說她表親很宅。": `あなたが小晴ちゃんの……！毎週お店に来てくれてたよ。いとこが電車オタクだって言ってた。`,
  "你就是新來的？太好了，午餐尖峰訂單爆了。三張單，全交給你。": `新人さん？助かった、ランチのピークで注文がパンクしてるんだ。三件、全部お願い。`,
  "你就是源先生說的那個人吧？幫大忙了，今晚我們的調查員全都出去了。": `あなたが源さんの言ってた子ね。助かるわ、今夜はうちの調査員がみんな出払ってて。`,
  "你是被威脅的，這不是你的錯。去交番把話說清楚——你是被害人。": `脅されてるんだ、君のせいじゃない。交番で全部話せ——君は被害者だ。`,
  "你瘋了嗎！這是天鵝船！": `正気ですか！スワンボートですよ！`,
  "你的回合：出一張手牌": `あなたの番：手札を一枚`,
  "你的本命會播嗎？閃亮☆電台！": `推しの曲、かかるかな？キラキラ☆ラジオ！`,
  "你被以現行犯逮捕！": `現行犯で逮捕する！`,
  "你認識一個叫小晴的臺灣女生嗎？她拿了你的傳單。": `小晴っていう台湾の女の子を知ってますか？あなたのチラシを受け取ったはずです。`,
  你贏了這局: `あなたの勝ち`,
  "你贏了！": `あなたの勝ち！`,
  "你跟著轟封路飆過半個東京，在東京車站前拍到了神城的司機交錢。": `轟について通行止めの東京を半周駆け抜け、東京駅前で神城の運転手の受け渡しを撮った。`,
  你輸了: `あなたの負け`,
  "你闖紅燈了，開一張青單。": `信号無視ですね。青切符を切ります。`,
  "你騎著借來的菜籃車，在剛開市的築地場外跟住廂型車，救出了小晴。她帶著詐騙集團的長者名單。": `借りたママチャリで、開いたばかりの築地場外でバンを追い、小晴を助け出した。彼女は詐欺グループの高齢者リストを持っていた。`,
  "來了來了——請問是哪位？": `はーい、どちらさま？`,
  "來了啊！今天也大聲點！": `来たな！今日も声出していけ！`,
  "來了啊！今晚也會很忙喔！": `来たか！今夜も忙しいぞ！`,
  "來來來，一千日圓！一千日圓就好！": `さあさあ、千円！千円でいいよ！`,
  "來來來，泡完澡就是要喝這個！咖啡牛奶，我請客！": `はいはい、お風呂上がりはこれよ！コーヒー牛乳、おごりだからね！`,
  來啦: `いらっしゃい`,
  "來啦。今天也拜託你了。": `あら、来たのね。今日もお願いね。`,
  "來啦，今天也拜託了。": `お、来たね。今日もよろしく。`,
  "來喔來喔！": `らっしゃい、らっしゃい！`,
  "來囉，歡迎！": `へい、らっしゃい！`,
  "來，一千圓！一千圓！": `はい、千円！千円！`,
  依序按方向鍵: `矢印の順に入力`,
  "依序放配料（叉燒↑ 蛋→ 筍乾↓ 蔥←）": `トッピングを順に（チャーシュー↑ 味玉→ メンマ↓ ねぎ←）`,
  依條例禁止拉客及招攬: `条例により客引き・客待ちは禁止されています`,
  "依照法律，失主要給拾得人百分之五到二十的謝禮。": `法律では、落とし主さんは拾った方に五〜二十パーセントのお礼をすることになっています。`,
