  偏硬: `かため`,
  "偏硬就早點起鍋，偏軟就多煮一下。配料的順序：叉燒、點的料、最後撒蔥。": `かためは早く、やわらかめは長く。トッピングはチャーシュー、注文の品、最後にねぎ。`,
