  "到上野了。地址是……沒有導航，就看電線桿和街角的門牌吧。": `上野に着いた。住所は……ナビなしで、電柱と角の住居表示を見ていこう。`,
  "到上野站。……熊貓已經不在了呢。": `上野駅まで。……パンダ、もういないんですよねえ。`,
  "到了——慢慢停下來。": `着いたぞ——ゆっくり止まれ。`,
  "到了！跑得不錯嘛。": `着いた！なかなかやるじゃねえか。`,
  "到新橋的 SL 廣場。跟同事約好了。": `新橋のSL広場まで。同僚と待ち合わせなんです。`,
  "到日本橋，橋頭放我下來就好。": `日本橋まで。橋のたもとで降ろしてください。`,
  "到有樂町的國際論壇。有場研討會。": `有楽町の国際フォーラムまで。学会なんです。`,
  "到東京站丸之內口。要趕新幹線，拜託了！": `東京駅の丸の内口まで。新幹線に乗るんです、お願いします！`,
  "到歌舞伎座。趕得上四點那一幕嗎？": `歌舞伎座まで。四時の幕に間に合いますか？`,
  "到神田明神。孫子要考試，去買御守。": `神田明神まで。孫が受験でね、お守りを買いに。`,
  "到神田站西口。今天要在高架橋下喝一杯。": `神田駅の西口まで。今日はガード下で一杯やるんです。`,
  "到秋葉原，電氣街口那邊。": `秋葉原まで。電気街口のほうで。`,
  "到築地場外。想去吃玉子燒。": `築地の場外まで。玉子焼きが食べたくて。`,
  "到聖路加醫院。去探病的。": `聖路加病院まで。お見舞いなんです。`,
  "刷醬：在對的時機刷三次": `タレを塗る：タイミングよく三回`,
