  "前面的車，靠左停下！": `前の車、左に寄せて止まりなさい！`,
  "剛剛在後街的女僕咖啡廳前看到一個，提著店裡的粉紅紙袋": `さっき裏通りのメイドカフェ前にいた。店のピンクの紙袋持ってた`,
  "剛剛那些是神城的人吧。那傢伙把我的車手一個一個挖走，去跑他的地下賽。": `さっきのは神城の手下だろ。あの野郎、うちのライダーを一人ずつ引き抜いて、闇レースに出してやがる。`,
  "剛剛，好的。": `さっき、ですね。はい。`,
  "剛好這位剛送來一個。為了確認，可以說說裡面有什麼嗎？": `ちょうど今、こちらの方が届けてくださいました。念のため、中身を教えていただけますか？`,
