  "勇樹不見了……神城。這就是那個「上面的人」。": `勇樹がいない……神城。そいつが「上の連中」か。`,
  "勇樹和其他人還在新橋的客服中心。今晚神城要把伺服器搬走。": `（中国語で）勇樹くんたちはまだ新橋のコールセンターにいる。今夜、神城がサーバーを移すって。`,
  "勇樹要搭末班山手線。你穿過上野站的迷宮，在車門關上前跳進車廂，在安靜的車廂裡一句一句勸他。他說了母親和身分證照片的事；到了新橋他還是逃進夜色。源さん的計程車停在你面前：「妙子打給我的。上車。」": `勇樹は終電の山手線に向かった。上野駅の迷路を抜けてドアが閉まる前に乗り込み、静かな車内で彼を説得した。母親のこと、身分証の写真のことを打ち明けたが、新橋で彼は夜の街へ逃げた。源さんのタクシーが止まる。「タエさんから電話があった。乗りな」`,
