  哈密瓜蘇打: `メロンソーダ`,
  "哎呀……真的幫我拿回來了？謝謝你，謝謝你。": `まあ……本当に取り返してくれたの？ありがとうねえ、ありがとう。`,
  "哎呀，再去續一攤！": `いやぁ、もう一軒行きます！`,
  "哎呀，日本的小孩都被教過，不能拿陌生人的糖果喔。蹲下來，跟他好好說吧。": `あらあら、知らない人からお菓子をもらっちゃダメって、日本の子は教わってるのよ。しゃがんで、ゆっくり話してあげて。`,
