  "啊——！搶劫！我的包包！": `あっ——！ひったくり！私のバッグ！`,
  "啊……有點散掉了呢。": `あ……ちょっと崩れてますね。`,
  "啊啊啊！": `きゃあああ！`,
  "啊，你來得正好。這孩子一直在哭，好像跟媽媽走散了……": `ああ、ちょうどよかった。この子、さっきからずっと泣いてて……お母さんとはぐれちゃったみたいなの。`,
  "啊，對不起……": `あっ、すみません……`,
  "啊，櫻花差不多要謝了吧。": `あ、桜ももう終わりかなあ。`,
  "啊，這樣啊！失禮了。祝你們賞花愉快。": `あ、そうですか！失礼しました。いいお花見を。`,
  "啊～泡得真舒服": `あ〜、いい湯だった`,
  "喂喂，客人都走啦！": `おいおい、客が帰っちまうぞ！`,
