  "喂，這邊空著吧？鋪一半給我們用嘛。": `ねえ、こっち空いてるよね？半分使わせてよ。`,
  喇叭: `クラクション`,
  "喔，今天也來啦。湯已經熬好了。": `お、今日も来たか。スープはできてるぞ。`,
  "喔，佐伯先生！好久不見啦。": `お、佐伯さん！久しぶりだねえ。`,
  "喔，你來啦。今晚我的腰不聽使喚。": `よう、来たか。今夜はおれの腰が言うことを聞かなくてな。`,
  "喔，回來啦。……客人下車時都在笑。開得好。": `おう、おかえり。……客がみんな笑って降りてった。いい運転だ。`,
  "喔，小晴的表親？那孩子一個禮拜前辭職了。說什麼「找到了活動的工作」。": `おう、小晴ちゃんの親戚かい。あの子なら一週間前に辞めたよ。「イベントの仕事が見つかった」ってさ。`,
