  "外送城午餐尖峰缺人！到神田的店家取餐，送到用日本地址（丁目-番-號）寫的客人家。餐點要放平、要準時；每趟有運費和速度獎金，日本沒有小費。": `出前城、ランチのピークで人手不足！神田の店で料理を受け取り、丁目・番・号の住所のお客さんへ。料理は水平に、時間内に。一件ごとの配達料とスピードボーナス（チップはなし）。`,
