  "她不在家啊！她七點前都在補習班！": `家にいないんだってば！七時まで塾なんだよ！`,
  "她只拍我們兩個，不會拍到你的臉。": `撮ってるのは俺たちだけ。君の顔は映らない。`,
  "她最後的訊息說，找到了一個「時薪很高的活動打工」。": `最後のメッセージで「時給のいいイベントのバイト」を見つけたって。`,
  "她的手機在我們這。人嘛……神城先生會好好「照顧」的。": `携帯ならこっちにある。本人は……神城さんがちゃんと「面倒見てる」よ。`,
  "她的手機還開著，只是被關了定位。我可以做一個追蹤器去抓它的訊號——零件清單給你。": `携帯はまだ生きてる。位置情報を切られてるだけ。電波を拾う追跡機なら作れるよ——はい、パーツのリスト。`,
  "好厲害！": `すごい！`,
