  "好好，我等一下就去。……這個，一點小心意，收下吧。不用客氣、不用客氣。": `はいはい、あとで行きますよ。……これ、少ないけどお礼。いいから、いいから。`,
  "好漂亮～！": `たまや〜！`,
  "好痛……好啦好啦，包包還你啦！": `いってえ……わかった、わかったよ、返すって！`,
  "好痛痛……好啦，還你、還你啦！": `いてて……わかった、返す、返すから！`,
  "好痛！": `痛っ！`,
  "好的。請問晚上公園開到幾點？我們可能會待到天黑。": `はい。夜は何時まで開いてますか？暗くなるまでいるかもしれなくて。`,
  "好的，我們會注意。辛苦了。": `はい、気をつけます。お疲れさまです。`,
  "好的，馬上來！": `はい、喜んで！`,
