  "店規：不能碰觸、拍照只能用拍立得。有人違規就有禮貌地提醒——我們這裡是健全的店喔。": `ルールはお触り禁止、撮影はチェキだけ。破る人には丁寧に注意してね。健全なお店だから。`,
