  "悠斗哭個不停。": `ゆうとは泣き止まない。`,
  "悠斗很勇敢喔。": `ゆうとくん、えらかったですよ。`,
  悠斗的媽媽: `ゆうとのママ`,
  "悠斗！": `ゆうと！`,
  "您好，我是小晴的表親，從臺北來的。小晴在嗎？": `こんにちは。小晴の従兄弟で、台北から来ました。小晴はいますか？`,
  "您沒事就好。警察說之後會請您去交番做筆錄。": `ご無事でよかったです。警察が、あとで交番でお話を聞きたいそうです。`,
  惠: `恵`,
  "想學烤雞肉串？一根一根看清楚——上色就翻面，焦了就是廢物。": `焼き鳥を覚えたい？一本一本よく見ろ。きつね色で返す、焦がしたら終わりだ。`,
  "想歇口氣，就到LAWSAN的咖啡。": `ひと息つくなら、ローサンのカフェで。`,
  愛心: `ハート`,
  感謝打賞: `投げ銭ありがとうございます`,
  "慢慢泡喔～": `ごゆっくり〜`,
  慢行: `徐行`,
  "戀愛訊號☆": `恋のシグナル☆`,
  "成人 {price}": `大人 {price}`,
  "成役了！": `役ができた！`,
  我: `阿傑`,
  "我一定會找到她的。": `必ず見つけます。`,
  "我不會白白幫一個陌生人。陪我打一局花札。輸贏不重要——我要看你怎麼收手。": `タダで余所者に手は貸さねえ。花札に付き合いな。勝ち負けじゃねえ——引き際を見せてもらう。`,
  "我不知道！我只拿到手機而已，人怎麼樣我不知道！": `知らねえよ！携帯渡されただけで、人のことなんか知らない！`,
  "我什麼都沒做！": `何もしてねえよ！`,
  "我以前也住過這附近喔。變了好多。": `昔、この辺に住んでたんですよ。ずいぶん変わったなあ。`,
  "我們不是警察，也不是他們那邊的人。": `俺たちは警察じゃない。あいつらの仲間でもない。`,
  "我們四個走進交番，今晚神城就會知道。小晴姊還在新橋，在他們手上……我不能害她。": `四人で交番に入ったら、今夜には神城に伝わる。小晴さんはまだ新橋に……あの人をそんな目にあわせられない。`,
  "我們沒有用繩子喔——倒是那邊那團圍了半片草地。": `うちはロープ使ってませんよ——あっちのグループは芝生半分囲ってますけど。`,
  "我剛剛就在人群裡追上你了。今天這條街上的便衣有二十個——只有騎車的那個有引擎。": `今、人混みで俺に捕まったろ。今日この通りに私服は二十人いる——エンジンがあるのはバイクの奴だけだ。`,
  "我去追鴿子……對不起。": `ハトさんおいかけてた……ごめんなさい。`,
  "我只是來找表妹的。": `従妹を探しに来ただけです。`,
  "我只是發傳單的！": `チラシ配ってるだけだって！`,
  "我叫悠斗，五歲。": `ぼく、ゆうと。五さい。`,
  我在下一站等你: `次の駅で　君を待つよ`,
  "我在念法律，夜間部。給我證據，不然就閃開。": `俺、夜間の法学部なんで。証拠を見せてください。でなきゃ、どいて。`,
  "我在扭蛋會館排在他後面！淺色的牛仔褲": `ガチャ会館で後ろに並んでた！薄い色のジーンズ`,
  "我在獅子像前面啦！……你又遲到了喔？": `ライオンの前にいるってば！……また遅刻？`,
  "我小時候在家玩賽車遊戲可是玩到天亮的。": `子供の頃、レースゲームを朝までやってたんだ。`,
  "我是寫旅遊部落格的柚子！今天一定要交「百年的東京」的專欄，剛剛卻在樓梯扭到腳……嘿嘿。": `旅ブログやってるゆずです！今日中に「百年の東京」のコラムを出さなきゃなのに、さっき階段で足をひねっちゃって……えへへ。`,
  "我沒做什麼啦！": `何もしてねえよ！`,
  "我的追蹤器還抓得到那支手機。你先跑去上野廣小路，搶在他前面——看他到底上幾樓。我打給你。": `追跡機はまだあの携帯を拾ってる。先に上野広小路まで走って、彼より先に着いて——本当に何階に行くか見て。電話するね。`,
  "我真的不知道！我只負責發傳單，人是上面的人帶走的……": `本当に知らねえって！俺はチラシ配るだけで、連れてくのは上の連中だ……`,
  "我老爸？他怎樣都好。我又不是為了他來的。": `親父？どうなろうが知らねえよ。そんな理由で来てねえ。`,
  "我腳不好，沒辦法陪你們走。那邊的地圖看板旁有公園職員，可以請他廣播「迷子のお知らせ」喔。": `私は足が悪くてねえ。あっちの案内板のところに公園の職員さんがいるから、迷子のお知らせを流してもらえるわよ。`,
  "我要！我要一袋！": `はい！ひとつちょうだい！`,
  我試著喊你的名字: `君の名前を　呼んでみたけど`,
  "我高中一百公尺跑十一秒。警報一響我就不見了——誰抓得到我？": `高校の百メートル、十一秒だぜ。警報が鳴ったら俺はもういない——誰が捕まえんだよ。`,
  房屋仲介: `不動産屋`,
  房屋資訊: `物件情報`,
  "所以他的司機在收錢。這證明他拿錢——跟他會怎麼對我們無關。": `つまり運転手が金を受け取ってる。金を取ってる証拠にはなっても、俺たちをどうするかとは関係ない。`,
