  "相機家電點數回饋百分之十。淀川相機。": `カメラも家電も、ポイント十パーセント還元。ヨドガワカメラ。`,
  "看一下、看一下！": `見てって、見てって！`,
  "看好了——路口直接甩過去！": `見てろ——交差点はドリフトで抜ける！`,
