  "看餐券就知道要什麼：湯頭、麵的硬度、配料。": `食券を見ればわかる。スープ、麺の硬さ、トッピングだ。`,
  "真好吃！": `うまい！`,
  "真是的……你跑去哪裡了！媽媽好擔心……": `もう……どこ行ってたの！心配したんだから……`,
  "真的、真的非常感謝您！一直陪著他……": `本当に、本当にありがとうございました！ずっと一緒にいてくださって……`,
  "真的假的？": `マジで？`,
  "真的嗎？太好了！大家，這邊這邊——": `本当ですか？助かります！みんな、こっちこっち——`,
  "真的太感謝了！你跑得好快。": `本当にありがとうございます！足、速いんですね。`,
  "真的幫了我大忙。謝謝您！": `本当に助かりました。ありがとうございました！`,
  "真的很抱歉，人等一下就到了。那邊的櫻花樹下好像還有空位喔。": `本当にすみません、もうすぐみんな来るんです。あっちの桜の下、まだ空いてるみたいですよ。`,
