  神保町旁的舊書店: `神保町寄りの古書店`,
  "神城今天被起訴了。詐欺、強盜未遂、恐嚇。打工者的身分證照片和手機，全部還回去了。": `神城は今日、起訴されました。詐欺、強盗未遂、脅迫。闇バイトの子たちの身分証の写真と携帯は、全部本人に返しました。`,
  "神城先生。關於詐欺與強盜未遂的嫌疑，請跟我們走一趟。": `神城さん。詐欺と強盗未遂の容疑で、ご同行願います。`,
  "神城搶了一艘天鵝船。你踩著另一艘追過不忍池，十七點的〈晚霞漸淡〉響起時，桐島在對岸銬上了他。": `神城はスワンボートを奪った。もう一艘で不忍池を追い、十七時の「夕焼け小焼け」が流れる中、桐島が対岸で手錠をかけた。`,
  "神城要搭山手線去上野，轉 Skyliner 去成田。": `神城は山手線で上野へ、スカイライナーで成田へ向かう。`,
  "神城那種人，叫小孩子大白天去搶東西，讓警察把整個上野翻過來。我們這一行，以前是有規矩的。": `神城みたいなのは、ガキに昼間から強盗させて、上野中にサツを呼び込む。昔はこの稼業にも筋ってもんがあった。`,
