  "詳細的我也不知道……少了她，我這邊缺人手。你幫我叫一下午，我就把知道的都告訴你。": `詳しいことは知らねえ……あの子が抜けて、こっちは人手が足りねえんだ。午後いっぱい手伝ってくれたら、知ってることは全部話すよ。`,
