  "迷路的孩子啊。叫什麼名字？……悠斗，五歲。媽媽的穿著呢？": `迷子ちゃんですね。お名前は？……ゆうとくん、五歳。お母さんの服装はわかりますか？`,
  "追上「搶劫犯」！緊跟在後讓他慌張，或直接把他撞倒": `「ひったくり犯」を追え！ぴったり付いて焦らせるか、ぶつけて止めろ`,
