  "追蹤器說，小晴的手機就在這條街上。我們只知道店裡的熟客看到的：深色外套、背後背包的男生。": `追跡機だと、小晴ちゃんの携帯はこの通りにある。分かってるのは、お店の常連さんが見た「暗い色のジャケットにリュックの男」だけ。`,
