  "那到新橋你帶我去。指給我看在哪裡就好，其他我來。": `じゃあ新橋で案内してくれ。場所を指さすだけでいい、あとは俺がやる。`,
  "那台機車——他要自己去搶鐘錶店！在他騎到店門口之前擋下他！": `あのバイク——自分で時計屋をやる気だ！店に着く前に止めろ！`,
  "那台機車，停下！": `そこのバイク、止まりなさい！`,
  "那天的直播已經破十萬觀看了喔！標題是「不忍池・天鵝船追緝」。": `あの日の配信、十万再生超えたよ！タイトルは「不忍池・スワンボート追跡」。`,
  "那就今晚不幹了。封鎖他們、換手機號碼，他們很快就會放棄的。": `じゃあ今夜で辞めろ。ブロックして番号変えれば、そのうち諦めるって。`,
  "那就更糟了……你們根本保護不了我。": `じゃあ余計ダメだ……あんたらじゃ俺を守れない。`,
