  轉一顆: `ハンドルを回す`,
  "放上綠色乖寶，車子乖乖的不會壞了！": `緑のグァイバオを置いたら、車がおとなしくなった！`,
  "槓龜，下一張會更好": `ハズレ。次こそ！`,
  特別獎: `特別賞`,
