  "成役後二選一：<b>「こいこい」</b>繼續拚更多分，或<b>「勝負」</b>現在收分。見好就收，也是一種本事。": `役ができたら二択：<b>「こいこい」</b>で続けてもっと稼ぐか、<b>「勝負」</b>で今すぐ上がるか。引き際も腕のうち。`,
