  "在 JR 車站入口按互動鍵，就能搭山手線（目前開放新橋到上野）。": `JR駅の入口で操作キーを押すと山手線に乗れる（現在は新橋〜上野間）。`,
  "地鐵站入口可以搭銀座線、日比谷線與丸之內線快速移動。": `地下鉄駅の入口から銀座線・日比谷線・丸ノ内線でスピーディーに移動できる。`,
  "週末中午起，銀座的中央通變成步行者天國，車子進不去。": `週末の昼から、銀座の中央通りは歩行者天国になり車は入れない。`,
  "東京街角到處都是自動販賣機，一瓶飲料大約 ¥160。": `東京の街角には自販機がどこにでもある。飲み物は1本およそ ¥160。`,
  "想回臺北？到東京車站八重洲口的機場巴士站。": `台北に帰りたい？東京駅八重洲口の空港バス乗り場へ。`,
  "按 {map} 開啟地圖；地圖上的「北」指向真正的北方，街道則順著山手線排列。": `{map} で地図を開く。地図の「北」は本当の北を指し、通りは山手線に沿って並んでいる。`,
  "按 {phone} 打開手機，「電車」可以導航到最近的車站。": `{phone} でスマホを開き、「電車」から最寄り駅へナビを設定できる。`,
