  "秋葉原的中央通兩旁都是電器行與動漫店。": `秋葉原の中央通りの両側には家電店とアニメショップがずらり。`,
  "街角的「交番」就是派出所，警察就在裡面。": `街角の「交番」は警察の詰所。中にはお巡りさんがいる。`,
