  "《舊金山狂飆》即將開放，先去《臺北狂飆》狂飆吧！": `《サンフランシスコラッシュ》はまもなく公開。それまで《臺北狂飆》で暴れよう！`,
  "《倫敦狂飆》目前只能從《臺北狂飆》的<b>松山機場</b>（或《香港狂飆》的香港站）搭狂飆航空前往。": `《ロンドンラッシュ》へは今のところ、《臺北狂飆》の<b>松山空港</b>（または《香港狂飆》の香港駅）から RUSH AIR で行くしかありません。`,
  "《倫敦狂飆》即將開放，先去《臺北狂飆》狂飆吧！": `《ロンドンラッシュ》はまもなく公開。それまで《臺北狂飆》で暴れよう！`,
