  "垃圾車的〈給愛麗絲〉響起時，全臺北都會出門倒垃圾。": `ゴミ収集車の「エリーゼのために」が流れると、台北中の人がゴミ出しに出てくる。`,
  "臺北的紅綠燈有倒數計時，黃燈別硬闖——測速照相會拍你。": `台北の信号はカウントダウン付き。黄色で突っ込むな——速度取締りカメラが見ている。`,
  "便利商店的茶葉蛋可以回血，一顆只要 13 元。": `コンビニの茶葉蛋で体力が回復する。1個たった 13 元。`,
  "機車可以鑽車縫，也能騎上人行道（但警察會看）。": `バイクは車の間をすり抜けられるし、歩道も走れる（ただし警察は見ている）。`,
  "按 {map} 開啟地圖，點一下就能設定導航。": `{map} で地図を開き、好きな場所を選ぶとナビを設定できる。`,
  "按 {phone} 打開手機：接任務、搭捷運、切換電台。": `{phone} でスマホを開く：ミッション受注、地下鉄、ラジオ切替。`,
  "走到機車、重機或汽車旁按 {enter} 就能騎上去。": `バイク・大型バイク・車のそばで {enter} を押すと乗れる。`,
  "下雨天路面濕滑，煞車距離會變長。": `雨の日は路面が滑りやすく、制動距離が伸びる。`,
  "捷運站入口可以快速移動到城市另一頭。": `地下鉄の駅入口から街の反対側まですばやく移動できる。`,
  "夜市晚上七點以後最熱鬧：雞排、臭豆腐、珍珠奶茶。": `夜市は夜7時以降が一番にぎやか：鶏排、臭豆腐、タピオカミルクティー。`,
  "騎樓是臺北人的雨天走廊，走在底下不會淋濕。": `騎楼は台北の人の雨の日の回廊。下を歩けば濡れない。`,
  "龍山寺建於 1738 年，是臺北最古老的廟宇之一。": `龍山寺は1738年創建、台北最古の寺院のひとつ。`,
