  "LINE 的內建瀏覽器不能「加入主畫面」，可用的記憶體也比較少，遊戲容易重新載入。先用 Safari 開啟《臺北狂飆》。": `LINEの内蔵ブラウザは「ホーム画面に追加」ができず、使えるメモリも少ないため、ゲームが再読み込みされやすくなります。まずSafariで《臺北狂飆》を開いてください。`,
