  "點網址列的分享 → 加入主畫面，就能全螢幕玩": `アドレスバーの共有 → ホーム画面に追加で全画面プレイ`,
  "點「⋯」→ 分享 → 加入主畫面，就能全螢幕玩": `「⋯」→ 共有 → ホーム画面に追加で全画面プレイ`,
  "點分享 → 加入主畫面，就能全螢幕玩": `共有 → ホーム画面に追加で全画面プレイ`,
  "iPhone 的 Safari 不支援網頁全螢幕。把《臺北狂飆》加到主畫面，從圖示開啟，就沒有網址列和工具列了。": `iPhoneのSafariはWebページの全画面表示に対応していません。《臺北狂飆》をホーム画面に追加してアイコンから開けば、アドレスバーもツールバーも消えます。`,
