  空白鍵: `スペース`,
  "{k:W}{k:A}{k:S}{k:D} 走路，移動滑鼠轉視角。按住 {sprint} 衝刺、{jump} 跳躍。": `{k:W}{k:A}{k:S}{k:D} で歩き、マウスで視点移動。{sprint} 長押しでダッシュ、{jump} でジャンプ。`,
  "{p:L} 走路、{p:R} 轉視角。按住 {sprint} 衝刺、{jump} 跳躍。": `{p:L} で歩き、{p:R} で視点移動。{sprint} 長押しでダッシュ、{jump} でジャンプ。`,
  "左下拖曳搖桿走路（推到底就會跑），右半邊滑動轉視角。": `左下のスティックをドラッグして歩く（最後まで倒すと走る）。画面右半分をスワイプで視点移動。`,
  "左搖桿走路（推到底跑）・右半邊滑動轉視角": `左スティックで歩く（倒し切ると走る）・右半分スワイプで視点移動`,
  騎車與開車: `乗り物`,
  "走到機車、重機或汽車旁按 {enter} 就能騎上去；對行駛中的車按 {enter} 是搶車（會被通緝）。": `バイク・大型バイク・車のそばで {enter} を押すと乗れる。走行中の車に {enter} を押すと強奪になる（手配される）。`,
  "靠近機車、重機或汽車時，點右下的 {enter} 就能騎上去。": `バイク・大型バイク・車に近づいたら、右下の {enter} をタップで乗れる。`,
  "靠近機車或汽車，點 {enter} 就能騎上去": `バイクや車に近づき {enter} をタップで乗車`,
  駕駛: `運転`,
  "{k:W} 油門、{k:S} 煞車／倒車、{k:A}{k:D} 轉向、{handbrake} 手煞車甩尾。{horn} 喇叭、{radio} 換電台、{enter} 下車。": `{k:W} アクセル、{k:S} ブレーキ／バック、{k:A}{k:D} ハンドル、{handbrake} サイドブレーキでドリフト。{horn} クラクション、{radio} ラジオ切替、{enter} 降車。`,
  "{p:RT} 油門、{p:LT} 煞車／倒車、{p:L} 轉向、{handbrake} 手煞車。{radio} 換電台、{enter} 下車。": `{p:RT} アクセル、{p:LT} ブレーキ／バック、{p:L} ハンドル、{handbrake} サイドブレーキ。{radio} ラジオ切替、{enter} 降車。`,
  "右下「油門」「煞車」踏板控制速度，左搖桿轉向，{handbrake} 甩尾，{enter} 下車。": `右下の「アクセル」「ブレーキ」ペダルで速度を調整、左スティックでハンドル、{handbrake} でドリフト、{enter} で降車。`,
  "踏板加速・搖桿轉向・{handbrake} 甩尾・{enter} 下車": `ペダルで加速・スティックでハンドル・{handbrake} ドリフト・{enter} 降車`,
  地圖與導航: `地図とナビ`,
  "按 {map} 打開地圖，點一下任何地方就會設定導航，小地圖會畫出路線。": `{map} で地図を開き、好きな場所をクリックするとナビを設定。ミニマップにルートが表示される。`,
  "點左上的地圖按鈕，再點一下任何地方就能設定導航。": `左上の地図ボタンをタップし、好きな場所をタップするとナビを設定できる。`,
  "點左上地圖，再點任一處設定導航": `左上の地図→好きな場所をタップでナビ設定`,
  "按 {phone} 打開手機：接任務、搭捷運導航、切換電台、拍照。": `{phone} でスマホを開く：ミッション受注、地下鉄ナビ、ラジオ切替、撮影。`,
  "點左上的手機按鈕：接任務、搭捷運導航、切換電台、拍照。": `左上のスマホボタンをタップ：ミッション受注、地下鉄ナビ、ラジオ切替、撮影。`,
  "左上手機：任務・捷運・電台・拍照": `左上のスマホ：ミッション・地下鉄・ラジオ・撮影`,
  "地圖上的「任」是任務起點。走進光圈按 {interact} 開始；也可以用手機接任務並導航過去。": `地図上の「任」はミッションの開始地点。光の輪に入って {interact} で開始。スマホでミッションを受けてナビで向かうこともできる。`,
  "「任」是任務起點：走進光圈點 {interact}": `「任」はミッション開始地点：光の輪に入り {interact} をタップ`,
  被通緝了: `指名手配`,
  "星星代表通緝等級。離開警察視線、躲出小地圖上的搜索圈，星星閃爍一陣子後就會消失。": `星の数は手配レベル。警察の視界から外れ、ミニマップの捜索範囲から出れば、星がしばらく点滅した後に消える。`,
  "躲出小地圖的搜索圈，星星就會消失": `ミニマップの捜索範囲から出れば星が消える`,
  "按 {k:Enter} 拍照存檔，{k:Esc} 離開。": `{k:Enter} で撮影・保存、{k:Esc} で終了。`,
  "按 {p:A} 拍照存檔，{p:B} 離開。": `{p:A} で撮影・保存、{p:B} で終了。`,
  "點右下「拍照」存檔，「離開」回到遊戲。": `右下の「撮影」で保存、「終了」でゲームに戻る。`,
